def transform2(grid):
    H, W = len(grid), len(grid[0])
    from collections import Counter
    cnt = Counter(v for r in grid for v in r)
    fill = cnt.most_common(1)[0][0]
    # separator rows/cols: line = second most common? use rows/cols that are uniform non-fill
    def sep_lines():
        sr = [i for i in range(H) if len(set(grid[i])) == 1 and grid[i][0] != fill]
        sc = [j for j in range(W) if len({grid[i][j] for i in range(H)}) == 1 and grid[0][j] != fill]
        return sr, sc
    sr, sc = sep_lines()
    # markers: cells on sep lines whose color differs from line color and fill
    line_colors = {grid[i][0] for i in sr} | {grid[0][j] for j in sc}
    markers = {}
    for i in sr:
        for j in sc:
            v = grid[i][j]
            if v not in line_colors and v != fill:
                markers.setdefault(v, []).append((i, j))
    mrows = sorted({i for m in markers.values() for i, j in m})
    mcols = sorted({j for m in markers.values() for i, j in m})
    # grid bands fully within marker extent
    rbands = []
    prev = None
    for i in sr:
        if prev is not None and prev >= mrows[0] and i <= mrows[-1]:
            rbands.append((prev, i))
        prev = i
    cbands = []
    prev = None
    for j in sc:
        if prev is not None and prev >= mcols[0] and j <= mcols[-1]:
            cbands.append((prev, j))
        prev = j
    out = [[fill] * len(cbands) for _ in rbands]
    for ri, (r0, r1) in enumerate(rbands):
        for ci, (c0, c1) in enumerate(cbands):
            cs = [grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1]]
            if len(set(cs)) == 1 and cs[0] in markers:
                out[ri][ci] = cs[0]
    return out

